-- GENERATED by backend/services/visa_engine/families/importer.py from law/A cards
-- and family_a.json. DO NOT EDIT BY HAND: change the cards, then regenerate with
--   python -m backend.services.visa_engine.families.importer --family A --emit-sql > <this file>
-- Only the Law columns are written on conflict; legacy columns (name, category, description,
-- duration, cost_visa, requirements, metadata) are never overwritten.

SET lock_timeout = '5s';
SET statement_timeout = '60s';

-- Guard: refuse to run if a row already holds one of these codes in another case
-- (the UNIQUE on code is case-sensitive, so the upsert below would add a duplicate).
DO $guard$
BEGIN
    IF EXISTS (SELECT 1 FROM visa_types WHERE code <> upper(code) AND upper(code) IN ('A1', 'A36', 'A37', 'A4')) THEN
        RAISE EXCEPTION 'visa_types holds a non-uppercase duplicate of a family code; fix the case first';
    END IF;
END
$guard$;

